% Reader question: Where can a stale write be refused?
% Claim: A transaction or version guard covers the full read-modify-write operation.
% Evidence: Two clients read version7; only the first version-checked mutation commits.
% Distinguish: Proposal, admission and durable commit.
% Grammar: A sequence, not a funnel suggesting WAL alone prevents lost updates.
% Acceptance: Identify why client B is refused.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd artifact,text width=3.4cm,align=center] (a) at (2.4,0) {Client A\\Read version 7; propose 8};
  \node[pd artifact,text width=3.4cm,align=center] (b) at (8.0,0) {Client B\\Read version 7; propose 8};
  \node[pd focus state,text width=6.4cm,align=center] (gate) at (5.2,-1.8) {Commit boundary\\Atomically check expected version and write};
  \node[pd ready state,text width=3.4cm,align=center] (commit) at (2.4,-3.6) {A admitted\\Version 8 durably committed};
  \node[pd breach state,text width=3.4cm,align=center] (reject) at (8.0,-3.6) {B refused\\Expected 7; actual 8};
  \draw[pd arrow] (a) -- (gate);
  \draw[pd arrow] (b) -- (gate);
  \draw[pd ready arrow] (gate) -- (commit);
  \draw[pd breach arrow] (gate) -- (reject);
  \node[pd note,text width=9.4cm,align=left] at (5.2,-5.3) {A serialized log records the accepted order. Preventing lost updates also requires a transaction or version check covering each complete operation.};

\end{tikzpicture}

% Reader question: What can a delegate pass onward?
% Claim: Every accepted child grant is a subset of its parent grant.
% Evidence: An illustrative path scope and expiry chain.
% Distinguish: Permitted narrowing and rejected widening.
% Grammar: A delegation chain with a refused branch.
% Acceptance: Trace which child request violates attenuation.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd identity state,text width=6.0cm,align=center] (parent) at (4.5,0) {Parent grant\\Read and write repository; expires 18:00};
  \node[pd focus state,text width=6.0cm,align=center] (child) at (4.5,-1.8) {Child grant\\Read and write docs; expires 17:00};
  \node[pd ready state,text width=6.0cm,align=center] (leaf) at (4.5,-3.6) {Accepted descendant\\Read docs only; expires 16:00};
  \draw[pd arrow] (parent) -- (child);
  \draw[pd ready arrow] (child) -- (leaf);
  \node[pd breach state,text width=6.0cm,align=center] (bad) at (4.5,-5.4) {Refused request\\Write source or extend expiry to 19:00};
  \draw[pd breach arrow] (child.east) -- (9.0,-1.8) -- (9.0,-5.4) -- (bad.east);

\end{tikzpicture}

% Reader question: Which path can an untrusted process use to leave its sandbox?
% Claim: A confinement claim depends on mediating all specified effect paths.
% Evidence: Sandbox, explicit egress boundary and configured checks.
% Distinguish: Mediated egress and excluded covert-channel claims.
% Grammar: Trust boundary diagram, not an absolute security shield.
% Acceptance: Name the enforced path and the remaining assumption.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd state,text width=3.6cm,align=center] (agent) at (3.0,0) {Untrusted process\\Private scratch and memory};
  \node[pd trust boundary,fit=(agent),inner sep=12pt] (sandbox) {};
  \node[pd title,text width=4.0cm,align=center] at (3.0,1.65) {Sandbox boundary};
  \node[pd focus state,text width=4.0cm,align=center] (gate) at (3.0,-2.2) {Egress mediator\\Destination, budget and content checks};
  \node[pd protocol state,text width=4.0cm,align=center] (dest) at (3.0,-4.4) {Authorized destination};
  \node[pd breach state,text width=2.9cm,align=center] (deny) at (8.0,-2.2) {Refused\\No admitted egress};
  \draw[pd arrow] (agent) -- (gate);
  \draw[pd ready arrow] (gate) -- (dest);
  \draw[pd breach arrow] (gate) -- (deny);
  \node[pd note,text width=9.2cm,align=left] at (5.0,-5.8) {Canary matching detects matching content. Timing channels, unmediated interfaces and arbitrary secrets require separate analysis.};

\end{tikzpicture}

% Reader question: How does an operator inspect a claim in a digest?
% Claim: References let a reader retrieve retained evidence behind a summary.
% Evidence: One digest entry leading to receipt and retained artifacts.
% Distinguish: Summary, commitment and available evidence.
% Grammar: Evidence lineage, not a reversible compression funnel.
% Acceptance: Follow an entry to evidence and say what the hash cannot recover.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd legible state,text width=6.0cm,align=center] (digest) at (5.2,0) {Fleet digest\\Task 42: tests passed; receipt R42};
  \node[pd focus state,text width=6.0cm,align=center] (receipt) at (5.2,-1.7) {Receipt R42\\Commit ID, test-run ID, artifact hashes};
  \node[pd artifact,text width=3.7cm,align=center] (diff) at (2.4,-3.5) {Retained diff\\Retrieve and check hash};
  \node[pd artifact,text width=3.7cm,align=center] (tests) at (8.0,-3.5) {Retained test log\\Retrieve and check hash};
  \draw[pd arrow] (digest) -- (receipt);
  \draw[pd arrow] (receipt) -- (diff);
  \draw[pd arrow] (receipt) -- (tests);
  \node[pd note,text width=9.2cm,align=left] at (5.2,-5.0) {A digest is a navigation aid. A commitment verifies retrieved content; it cannot reconstruct missing artifacts or establish their semantic correctness.};

\end{tikzpicture}

% Reader question: What survives when a process crashes?
% Claim: A durable principal can be bound to successive distinct process instances.
% Evidence: Principal A and two instance epochs.
% Distinguish: Principal, process identity and renewed authority.
% Grammar: Identity timeline, not automatic state resurrection.
% Acceptance: Identify why instance2 needs a fresh binding.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd identity state,text width=8.6cm,align=center] (principal) at (5.2,0) {Durable principal A\\Key, obligations and retained receipts};
  \node[pd artifact,text width=3.7cm,align=center] (old) at (2.4,-2) {Instance 1\\PID 412; epoch 7};
  \node[pd focus state,text width=3.7cm,align=center] (new) at (8.0,-2) {Instance 2\\PID 919; epoch 8};
  \draw[pd arrow] (principal.south west) -- (old.north);
  \draw[pd arrow] (principal.south east) -- (new.north);
  \draw[pd breach arrow] (old) -- node[pd tag,text width=1.2cm,align=center] {crash} (new);
  \node[pd note,text width=9.2cm,align=left] at (5.2,-3.7) {The new instance proves a fresh binding and reacquires valid authority. Principal continuity does not revive expired leases or recover unrecorded state.};

\end{tikzpicture}

% Reader question: Which resources are held until verification and settlement?
% Claim: Payment, collateral, evidence and settlement have separate roles.
% Evidence: A simple escrowed task contract.
% Distinguish: Funds held, evidence judged and transfers finalized.
% Grammar: A flow of obligations, not an unconditional incentive claim.
% Acceptance: Locate the evidence decision before fund release.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd value state,text width=3.7cm,align=center] (payment) at (2.4,0) {Buyer payment\\Compensates accepted work};
  \node[pd value state,text width=3.7cm,align=center] (bond) at (8.0,0) {Worker collateral\\Secures specified liabilities};
  \node[pd state,text width=6.0cm,align=center] (hold) at (5.2,-1.8) {Escrow holds separate balances};
  \node[pd artifact,text width=6.0cm,align=center] (evidence) at (5.2,-3.5) {Evidence decision\\Apply the agreed verifier or adjudicator};
  \node[pd focus state,text width=6.0cm,align=center] (settle) at (5.2,-5.2) {Settlement\\Release, refund or slash under the contract};
  \draw[pd arrow] (payment) -- (hold);
  \draw[pd arrow] (bond) -- (hold);
  \draw[pd arrow] (hold) -- (evidence);
  \draw[pd arrow] (evidence) -- (settle);

\end{tikzpicture}

% Reader question: How can a contested outcome reach a terminal decision?
% Claim: A bond funds a specified procedure; deterrence needs an incentive model.
% Evidence: Task, audit, contest, appeal and settlement.
% Distinguish: Evidence evaluation and contractual finality.
% Grammar: A process with explicit branches, not an infallible justice device.
% Acceptance: Trace an appealed audit to a final decision.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd value state,text width=5.6cm,align=center] (bond) at (5.2,0) {Agree the contract; post bond};
  \node[pd state,text width=5.6cm,align=center] (task) at (5.2,-1.4) {Perform work; retain evidence};
  \node[pd focus state,text width=5.6cm,align=center] (audit) at (5.2,-2.8) {Audit under a specified sampling rule};
  \node[pd ready state,text width=3.6cm,align=center] (accept) at (2.4,-4.4) {Uncontested outcome};
  \node[pd state,text width=3.6cm,align=center] (appeal) at (8.0,-4.4) {Contest and appeal\\Named decision-maker};
  \node[pd terminal,text width=5.6cm,align=center] (settle) at (5.2,-6.2) {Contractual finality and settlement};
  \draw[pd arrow] (bond) -- (task);
  \draw[pd arrow] (task) -- (audit);
  \draw[pd arrow] (audit) -- (accept);
  \draw[pd arrow] (audit) -- (appeal);
  \draw[pd arrow] (accept) -- (settle);
  \draw[pd arrow] (appeal) -- (settle);

\end{tikzpicture}

% Reader question: Who decides whether a remote request may execute?
% Claim: The receiver verifies evidence under its own admission policy.
% Evidence: Two independently administered hosts and an untrusted relay.
% Distinguish: Transport, verification and local authority.
% Grammar: Trust-domain sequence, not shared-sovereignty imagery.
% Acceptance: Locate the receiving admission decision.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd identity state,text width=6.0cm,align=center] (a) at (4.0,0) {Host A\\Signs request and supporting evidence};
  \node[pd protocol state,text width=6.0cm,align=center] (relay) at (4.0,-1.7) {Untrusted relay\\Carries signed bytes};
  \node[pd focus state,text width=6.0cm,align=center] (b) at (4.0,-3.4) {Host B admission check\\Trust, scope, freshness and local policy};
  \node[pd ready state,text width=3.5cm,align=center] (run) at (2.3,-5.2) {Admit locally\\Execute within local limits};
  \node[pd breach state,text width=3.5cm,align=center] (deny) at (7.7,-5.2) {Refuse locally\\Return a refusal receipt};
  \draw[pd arrow] (a) -- (relay);
  \draw[pd arrow] (relay) -- (b);
  \draw[pd ready arrow] (b) -- (run);
  \draw[pd breach arrow] (b) -- (deny);

\end{tikzpicture}

% Reader question: where does BDI reconsider an active plan?
% Claim: event, option and intention selection are distinct, with failure recovery.
% Evidence: AgentSpeak-style operational semantics in the surrounding section.
% Distinguish: beliefs, applicable plans, committed intentions and execution.
% Grammar: a control-flow diagram; a paradigm taxonomy would hide the loop.
% Acceptance: trace one failed action back to a fresh event without crossing text.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]
  \node[pd artifact,text width=3.4cm,align=center] (events) at (2.3,0)
    {Event queue\\Perceptions and goals};
  \node[pd artifact,text width=3.4cm,align=center] (beliefs) at (8.0,0)
    {Belief base\\Current observations};
  \node[pd focus state,text width=3.4cm,align=center] (select) at (2.3,-1.6)
    {Select an event\\\pdfigmath{$S_E$}};
  \node[pd artifact,text width=3.4cm,align=center] (plans) at (8.0,-1.6)
    {Plan library\\Triggers and contexts};
  \node[pd focus state,text width=5cm,align=center] (option) at (5.15,-3.2)
    {Find applicable plans; select one\\\pdfigmath{$S_O$}};
  \node[pd focus state,text width=5cm,align=center] (intention) at (5.15,-4.8)
    {Commit to an intention; select its next step\\\pdfigmath{$S_I$}};
  \node[pd state,text width=3.4cm,align=center] (act) at (5.15,-6.4)
    {Execute an action\\Observe the result};
  \node[pd ready state,text width=3.4cm,align=center] (ok) at (2.3,-8.0)
    {Success\\Advance the plan};
  \node[pd breach state,text width=3.4cm,align=center] (fail) at (8.0,-8.0)
    {Failure\\Post \texttt{-!g}; seek recovery};
  \draw[pd arrow] (events) -- (select);
  \draw[pd arrow] (select) -- (option);
  \draw[pd arrow] (beliefs.east) -- (10.2,0) -- (10.2,-3.2) -- (option.east);
  \draw[pd arrow] (plans) -- (option);
  \draw[pd arrow] (option) -- (intention);
  \draw[pd arrow] (intention) -- (act);
  \draw[pd ready arrow] (act) -- (ok);
  \draw[pd breach arrow] (act) -- (fail);
  \draw[pd ready arrow] (ok.west) -- (0,-8.0) -- (0,-4.8) -- (intention.west);
  \draw[pd breach arrow] (fail.east) -- (10.9,-8.0) -- (10.9,1.0) -- (2.3,1.0) -- (events.north);
\end{tikzpicture}

% Reader question: When does each communicating process continue?
% Claim: Asynchronous send and synchronous rendezvous have different blocking semantics.
% Evidence: Two processes exchanging one message in each panel.
% Distinguish: Mailbox delivery and paired readiness.
% Grammar: Two aligned sequence panels, not mixed timing icons.
% Acceptance: Say which sender can proceed before the receiver is ready.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd title,text width=10cm,align=center] at (5.2,0) {Asynchronous mailbox};
  \node[pd label,text width=2.7cm,align=center] at (1.5,-0.8) {Sender A};
  \node[pd label,text width=2.7cm,align=center] at (8.8,-0.8) {Receiver B};
  \draw[pd guide] (1.5,-1.2) -- (1.5,-2.7);
  \draw[pd guide] (8.8,-1.2) -- (8.8,-2.7);
  \draw[pd arrow] (1.5,-1.5) -- node[pd tag,text width=4.2cm,align=center] {enqueue message} (8.8,-2.5);
  \node[pd label,text width=3.3cm,align=center] at (1.5,-3.0) {A continues};
  \node[pd label,text width=3.3cm,align=center] at (8.8,-3.0) {B receives later};
  \draw[pd hairline] (0,-4.0) -- (10.4,-4.0);
  \node[pd title,text width=10cm,align=center] at (5.2,-4.7) {Synchronous rendezvous};
  \node[pd label,text width=2.7cm,align=center] at (1.5,-5.5) {Sender A};
  \node[pd label,text width=2.7cm,align=center] at (8.8,-5.5) {Receiver B};
  \draw[pd guide] (1.5,-5.9) -- (1.5,-8.0);
  \draw[pd guide] (8.8,-5.9) -- (8.8,-8.0);
  \draw[pd focus rule] (1.5,-6.1) -- (1.5,-7.0);
  \draw[pd arrow] (1.5,-7.0) -- node[pd tag,text width=4.2cm,align=center] {both ready: communicate} (8.8,-7.0);
  \node[pd label,text width=3.3cm,align=center] at (1.5,-8.4) {A resumes};
  \node[pd label,text width=3.3cm,align=center] at (8.8,-8.4) {B resumes};

\end{tikzpicture}

