% Reader question: What does a speech act ask its receiver to do?
% Claim: A message kind states communicative intent, not physical enforcement.
% Evidence: Request, inform and propose examples.
% Distinguish: Requested action, asserted fact and offered contract.
% Grammar: Three short protocol rows with concrete messages.
% Acceptance: Distinguish an assertion from a verified fact.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd title,text width=2.0cm,align=center] at (1.1,0) {Act};
  \node[pd title,text width=4.0cm,align=center] at (4.3,0) {Message};
  \node[pd title,text width=3.0cm,align=center] at (8.7,0) {Receiver decision};
  \draw[pd hairline] (0,-0.6) -- (10.4,-0.6);
  \node[pd label,text width=2.0cm,align=center] (req) at (1.1,-1.6) {\texttt{request}};
  \node[pd artifact,text width=3.4cm,align=center] (reqmsg) at (4.3,-1.6) {Run migration M};
  \node[pd label,text width=2.8cm,align=center] at (8.7,-1.6) {Agree or refuse; then report outcome};
  \draw[pd arrow] (req) -- (reqmsg);
  \draw[pd arrow] (6.2,-1.6) -- (7.1,-1.6);
  \draw[pd hairline] (0,-2.7) -- (10.4,-2.7);
  \node[pd label,text width=2.0cm,align=center] (inf) at (1.1,-3.7) {\texttt{inform}};
  \node[pd artifact,text width=3.4cm,align=center] (infmsg) at (4.3,-3.7) {Migration M completed};
  \node[pd label,text width=2.8cm,align=center] at (8.7,-3.7) {Assess the assertion and its evidence};
  \draw[pd arrow] (inf) -- (infmsg);
  \draw[pd arrow] (6.2,-3.7) -- (7.1,-3.7);
  \draw[pd hairline] (0,-4.8) -- (10.4,-4.8);
  \node[pd label,text width=2.0cm,align=center] (prop) at (1.1,-5.8) {\texttt{propose}};
  \node[pd artifact,text width=3.4cm,align=center] (propmsg) at (4.3,-5.8) {Run M for agreed payment};
  \node[pd label,text width=2.8cm,align=center] at (8.7,-5.8) {Accept or reject the proposal};
  \draw[pd arrow] (prop) -- (propmsg);
  \draw[pd arrow] (6.2,-5.8) -- (7.1,-5.8);

\end{tikzpicture}

% Reader question: How does a contractor obtain and close an assignment?
% Claim: Contract Net allocation precedes local admission and settlement.
% Evidence: Manager M and contractor C with six ordered messages.
% Distinguish: Bidding, selection, execution and evidence.
% Grammar: A sequence diagram with named actors.
% Acceptance: Trace the award before the execution receipt.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd title,text width=3.4cm,align=center] at (1.4,0) {Manager M};
  \node[pd title,text width=3.4cm,align=center] at (9.0,0) {Contractor C};
  \draw[pd guide] (1.4,-0.6) -- (1.4,-8.5);
  \draw[pd guide] (9.0,-0.6) -- (9.0,-8.5);
  \draw[pd arrow] (1.4,-1.3) -- node[pd tag,text width=5.2cm,align=center] {1. Call for proposals} (9.0,-1.3);
  \draw[pd arrow] (9.0,-2.6) -- node[pd tag,text width=5.2cm,align=center] {2. Bid or refuse} (1.4,-2.6);
  \draw[pd arrow] (1.4,-3.9) -- node[pd tag,text width=5.2cm,align=center] {3. Award with explicit terms} (9.0,-3.9);
  \node[pd focus state,text width=6.0cm,align=center] at (5.2,-5.4) {4. Contractor obtains local authority\\and executes within agreed limits};
  \draw[pd arrow] (9.0,-6.8) -- node[pd tag,text width=5.2cm,align=center] {5. Return result and evidence} (1.4,-6.8);
  \draw[pd ready arrow] (1.4,-8.1) -- node[pd tag,text width=5.2cm,align=center] {6. Settle under the contract} (9.0,-8.1);

\end{tikzpicture}

% Reader question: Does observing another agent reveal everything it knows?
% Claim: Observation is directional and limited by the observation relation.
% Evidence: Supervisor S sees A; A sees x; S does not see x directly.
% Distinguish: Direct visibility and higher-order knowledge.
% Grammar: An observation graph, not a claim of security from geometry.
% Acceptance: Explain why two arrows do not imply transitive direct observation.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd focus state,text width=3.0cm,align=center] (s) at (2.0,0) {Supervisor S};
  \node[pd state,text width=3.0cm,align=center] (a) at (8.0,0) {Agent A};
  \node[pd artifact,text width=3.0cm,align=center] (x) at (8.0,-2.5) {Object x};
  \draw[pd arrow] (s) -- node[pd tag,text width=1.5cm,align=center] {sees A} (a);
  \draw[pd arrow] (a) -- node[pd tag,text width=1.5cm,align=center] {sees x} (x);
  \node[pd note,text width=9.5cm,align=left] at (5.2,-4.3) {Knowing that A observes x requires assumptions about A's observation relation. It is not the same as S observing x, and neither property establishes absence of covert channels.};

\end{tikzpicture}

% Reader question: Can individually consistent rankings produce a majority cycle?
% Claim: This three-voter profile gives a Condorcet cycle.
% Evidence: The explicit rankings and three two-to-one pairwise votes.
% Distinguish: A possible majority cycle and Arrows general impossibility hypotheses.
% Grammar: A ranking table plus cycle, not a governance escape device.
% Acceptance: Recount each pairwise majority.
\pdfigurehue{pdcobalt}%
