% Reader question: Which material must enter the model context now?
% Claim: Staged loading separates discovery, instructions and execution.
% Evidence: Four artifact roles, with conditional retrieval.
% Distinguish: Discovery metadata, task text, references and host code.
% Grammar: A retrieval dependency graph, not invented frequency measurements.
% Acceptance: Identify which text is loaded only when needed.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd artifact,text width=6.0cm,align=center] (meta) at (5.2,0) {Discovery metadata\\Name, purpose and activation conditions};
  \node[pd focus state,text width=6.0cm,align=center] (skill) at (5.2,-1.9) {Selected skill instructions\\Load when the task needs them};
  \node[pd artifact,text width=3.7cm,align=center] (refs) at (2.4,-3.9) {Referenced material\\Retrieve relevant sections};
  \node[pd state,text width=3.7cm,align=center] (code) at (8.0,-3.9) {Host-executed scripts\\Return bounded results};
  \draw[pd arrow] (meta) -- (skill);
  \draw[pd arrow] (skill) -- (refs);
  \draw[pd arrow] (skill) -- (code);
  \node[pd note,text width=9.4cm,align=left] at (5.2,-5.5) {Context savings depend on what is retrieved and what the tools return. This architecture alone does not establish a usage frequency or an exponential reduction.};

\end{tikzpicture}

% Reader question: which hook can prevent an effect, and which runs afterwards?
% Claim: a pre-tool veto precedes execution; post-tool checks cannot undo it.
% Evidence: lifecycle ordering and illustrative cases in the adjacent section.
% Distinguish: proposed action, admission decision, effect and closeout.
% Grammar: sequence with a refusal branch, not a circular decorative loop.
% Acceptance: locate the effect boundary and trace refusal without reaching it.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]
  \node[pd artifact,text width=5cm,align=center] (start) at (4.1,0)
    {Session and turn setup\\\texttt{SessionStart}, \texttt{UserPromptSubmit}};
  \node[pd state,text width=5cm,align=center] (propose) at (4.1,-1.5)
    {Deliberation proposes a tool call};
  \node[pd focus state,text width=5cm,align=center] (gate) at (4.1,-3)
    {Pre-execution admission check\\\texttt{PreToolUse}};
  \node[pd breach state,text width=2.0cm,align=center] (refuse) at (9.0,-3)
    {Refuse\\No tool effect};
  \node[pd ready state,text width=5cm,align=center] (execute) at (4.1,-4.5)
    {Admitted tool executes\\Within its configured sandbox};
  \node[pd state,text width=5cm,align=center] (post) at (4.1,-6)
    {Record result; inspect output\\\texttt{PostToolUse}};
  \node[pd terminal,text width=5cm,align=center] (stop) at (4.1,-7.5)
    {Closeout checks\\\texttt{Stop}: accept or request more work};
  \draw[pd arrow] (start) -- (propose);
  \draw[pd arrow] (propose) -- (gate);
  \draw[pd breach arrow] (gate) -- (refuse);
  \draw[pd ready arrow] (gate) -- (execute);
  \draw[pd arrow] (execute) -- (post);
  \draw[pd arrow] (post) -- (stop);
  \draw[pd arrow] (post.west) -- (0.5,-6) -- (0.5,-1.5) -- (propose.west);
  \node[pd note,text width=2.3cm,align=left,anchor=north] at (9,-4.4)
    {A post-tool formatter changes an existing result; it is not a pre-effect veto.};
\end{tikzpicture}

% Reader question: Which unsafe transition can a supervisor disable?
% Claim: A controller can disable controllable events, but cannot disable an uncontrollable event.
% Evidence: Safe state, candidate write and externally caused crash.
% Distinguish: Controllable and uncontrollable event sets.
% Grammar: An automaton with named transitions, not a universal safety gate.
% Acceptance: Identify the event the supervisor cannot block.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd automaton focus,text width=1.4cm,align=center] (safe) at (5.2,0) {Safe};
  \node[pd automaton state,text width=1.4cm,align=center] (next) at (1.4,-3.0) {Safe next};
  \node[pd automaton state,text width=1.4cm,align=center] (bad) at (9.0,-3.0) {Unsafe};
  \node[pd automaton state,text width=1.4cm,align=center] (crash) at (5.2,-5.4) {Crash};
  \draw[pd ready arrow] (safe) -- node[pd tag,text width=2.0cm,align=center] {legal write\\enabled} (next);
  \draw[pd breach arrow] (safe) -- node[pd tag,text width=2.0cm,align=center] {illegal write\\disabled} (bad);
  \draw[pd arrow] (safe) -- node[pd tag,text width=2.4cm,align=center] {uncontrollable\\hardware failure} (crash);
  \node[pd note,text width=9.6cm,align=left] at (5.2,-7.0) {A safety language must admit every uncontrollable continuation of its permitted prefixes. Partial observation imposes an additional implementability condition.};

\end{tikzpicture}

% Reader question: How does a proposed action become an observed result?
% Claim: Deliberation, admission, execution and evidence have separate responsibilities.
% Evidence: A single proposed operation and its recorded outcome.
% Distinguish: Probabilistic proposal and explicitly mediated effects.
% Grammar: Closed control loop with refusal, not interchangeable abstract layers.
% Acceptance: Locate both the admission decision and returned evidence.
\pdfigurehue{pdcobalt}%
\begin{tikzpicture}[pd figure,x=1cm,y=1cm]

  \node[pd artifact,text width=5.8cm,align=center] (plan) at (4.4,0) {Deliberation\\Propose an operation};
  \node[pd focus state,text width=5.8cm,align=center] (admit) at (4.4,-1.8) {Admission boundary\\Check authority and decidable guards};
  \node[pd state,text width=5.8cm,align=center] (exec) at (4.4,-3.6) {Confined execution\\Apply admitted effects};
  \node[pd legible state,text width=5.8cm,align=center] (receipt) at (4.4,-5.4) {Evidence\\Record the observed outcome};
  \node[pd breach state,text width=1.5cm,align=center] (deny) at (9.5,-1.8) {Refuse};
  \draw[pd arrow] (plan) -- (admit);
  \draw[pd ready arrow] (admit) -- (exec);
  \draw[pd arrow] (exec) -- (receipt);
  \draw[pd breach arrow] (admit) -- (deny);
  \draw[pd arrow] (receipt.west) -- (0.6,-5.4) -- (0.6,0) -- (plan.west);

\end{tikzpicture}

