  };

  % Lifelines (vertical dashed)
  \draw[pd guide] (1.35, 7.9) -- (1.35, 1.2);
  \draw[pd guide] (4.30, 7.9) -- (4.30, 1.2);
  \draw[pd guide] (7.25, 7.9) -- (7.25, 1.2);
  \draw[pd guide] (10.15, 7.9) -- (10.15, 1.2);

  % 1. Initial Grant (t = 0s)
  \draw[pd focus rule, -{Stealth[length=3.5pt,width=2.5pt]}, draw=pdviolet] (4.30, 7.1) -- (1.35, 7.1)
    node[pos=0.5, above=1pt, font=\pdfiglabelsize, text=pdviolet, fill=pdpage, inner xsep=4pt, inner ysep=3.5pt] {grant: epoch 104 (TTL 60s)};

  % 2. Stall / Pause on Agent 1 Lifeline
  \node[pd state, draw=pderror, fill=pderror!6, text width=2.1cm, align=center, inner ysep=4.5pt] at (1.35, 4.7) {
    \textbf{\color{pderror}Pause (65s)}\\[2pt]
    {\color{pderror}exceeds TTL}\\[2pt]
    {\pdfigsub rate-limit stall}
  };

  % 3. Kernel Expiry & Reassignment
  \node[pd state, draw=pdcobalt, fill=pdcobalt!8, text width=2.4cm, align=center, inner ysep=4pt] at (4.30, 5.8) {
    \textbf{\color{pdcobalt}Lease Expired}\\[1pt]
    \texttt{epoch 104 $\to$ 105}
  };
  \draw[pd focus rule, -{Stealth[length=3.5pt,width=2.5pt]}, draw=pdteal] (4.30, 4.4) -- (7.25, 4.4)
    node[pos=0.5, above=1pt, font=\pdfiglabelsize, text=pdteal, fill=pdpage, inner xsep=4pt, inner ysep=3.5pt] {reassign: epoch 105};

  % 4. Agent 2 Valid Write & Commit
  \draw[pd focus rule, -{Stealth[length=3.5pt,width=2.5pt]}, draw=pdteal] (7.25, 3.5) -- (10.15, 3.5)
    node[pos=0.5, above=1pt, font=\pdfiglabelsize, text=pdteal, fill=pdpage, inner xsep=4pt, inner ysep=3.5pt] {\texttt{write} (epoch 105)};
  \draw[pd focus rule, -{Stealth[length=3.5pt,width=2.5pt]}, draw=pdteal] (10.15, 2.7) -- (7.25, 2.7)
    node[pos=0.5, above=1pt, font=\pdfiglabelsize, text=pdteal, fill=pdpage, inner xsep=4pt, inner ysep=3.5pt] {\textbf{\color{pdteal}200 OK} ($105 \ge 105$)};

  % 5. Agent 1 Wakes Up and Sends Late Write
  \draw[pd breach rule, -{Stealth[length=3.5pt,width=2.5pt]}] (1.35, 2.0) -- (10.15, 2.0)
    node[pos=0.60, above=1pt, font=\pdfiglabelsize, text=pderror, fill=pdpage, inner xsep=4pt, inner ysep=3.5pt] {\textbf{Late Write:} \texttt{PUT} (stale epoch 104)};

  % 6. Broker Rejection Response
  \draw[pd breach rule, dashed, -{Stealth[length=3.5pt,width=2.5pt]}] (10.15, 1.3) -- (1.35, 1.3)
    node[pos=0.45, above=1pt, font=\pdfiglabelsize, text=pderror, fill=pdpage, inner xsep=4pt, inner ysep=3.5pt] {\textbf{412 Precondition Failed} (rejected: carried $104 < 105$)};

  % Invariant banner at bottom
  \node[pd state, fill=pdink!3, draw=pdink!30, text width=10.8cm, align=center, inner ysep=4pt] at (5.7, 0.45) {
    \textbf{Fencing Invariant (Theorem~\ref{thm:exclusion}):} Reassignment increments the monotonic epoch ($104 \to 105$). Downstream effect brokers reject mutations bearing stale epochs, eliminating silent write-races under arbitrary agent pause.
  };
\end{tikzpicture}
\caption{Reassignment advances the fencing epoch. When agent $\alpha_{\text{auth}}$ pauses past its 60s lease TTL, the kernel increments the epoch to 105 and reassigns \texttt{src/auth/jwt.ts} to $\alpha_{\text{worker}}$. The downstream storage broker rejects $\alpha_{\text{auth}}$'s late write bearing epoch 104 with \texttt{412 Precondition Failed}, preventing silent corruption. [internal, Theorem~\ref{thm:exclusion}]}
\label{fig:swk-fencing-epoch}
\end{figure}

