    (wire) at (5.33,4.86)
    {same bytes on the untrusted wire: \texttt{alg=none} + tampered payload};
  \node[pd title,anchor=south] at (\xL,5.48) {A \quad header-selected};
  \node[pd title,anchor=south] at (\xR,5.48) {B \quad issuer-pinned};

  \node[pd state,minimum width=4.45cm] (header) at (\xL,3.22)
    {reads algorithm from token header};
  \node[pd warn state,minimum width=4.45cm] (none) at (\xL,2.12)
    {selects \texttt{none}; no signature check};
  \node[pd breach state,minimum width=4.45cm] (accept) at (\xL,1.02)
    {accepts forged token};

