    (104,0)--(163,0)--(173,10)--(173,44)--(104,44)--cycle;
  \draw[draw=pdteal,line width=.8pt] (163,0)--(163,10)--(173,10);
  \node[cl text,font=\pdfiglabelbold] (grant) at (115,15) {Grant $g$};
  \node[cl text] (active) at (115,32) {active};
  \draw[cl flow,draw=pdamber] (182,26)--(241,26);
  \node[cl edge] (expiry) at (209,12) {expiry / revoke};
  \draw[draw=pdamber,line width=.9pt] (246,17)--(246,40);
  \draw[draw=pdamber,line width=.9pt] (249,17)--(249,40);
  \node[cl text,text width=65pt] (removed) at (258,28)
    {$g$ removed\\from active set};
  \draw[pd hairline] (0,64)--(323,64);

  % Action decisions are not grant states. Re-read validity for every x.
  \node[cl text,font=\pdfiglabelbold] (each) at (30,89)
    {For every action $x$, check current $g$};
  \draw[draw=pdinkmuted,line width=.7pt] (30,110) rectangle (191,248);
  \node[cl text,font=\pdfiglabelbold] (conjunction) at (42,126) {All five must hold (AND)};
  \node[cl text] (scope) at (42,150) {$x$ in scope};
  \node[cl text] (stakes) at (42,170) {$\mathrm{stakes}(x)\le s_{\max}$};
  \node[cl text] (reversibility) at (42,190) {$\mathrm{reversibility}(x)\ge v_{\min}$};
  \node[cl text] (unexpired) at (42,210) {$g$ unexpired};
  \node[cl text] (unrevoked) at (42,230) {$g$ unrevoked};

  \draw[cl flow,draw=pdteal] (191,148)--(240,148);
  \node[cl edge] (all) at (215,134) {all five};
  \node[cl text,font=\pdfiglabelbold,text=pdteal] (admit) at (250,148) {Admit};
  \node[cl text] (permission) at (250,165) {may act};
  \node[cl text] (noasking) at (250,182) {without asking};
  \draw[cl flow,draw=pdamber] (191,215)--(240,215);
  \node[cl edge] (otherwise) at (218,198) {otherwise};
  \node[cl text,font=\pdfiglabelbold] (escalate) at (250,215) {Escalate};
  \node[cl text] (recipient) at (250,232) {to operator};
  \node[cl text] (noexecution) at (250,249) {no automatic act};

  % This loop returns to the next action check, never to the grant-state spine.
  \draw[cl flow,draw=pdinkmuted] (30,270)--(10,270)--(10,89)--(22,89);
  \node[cl text] (next) at (40,270) {Next candidate: recheck, never renew};

  % A taken action requires a record; admission alone is not an action taken.
  \draw[draw=pdinkmuted,line width=.7pt,fill=pdpage]
    (30,293)--(298,293)--(310,305)--(310,344)--(30,344)--cycle;
  \draw[draw=pdinkmuted,line width=.7pt] (298,293)--(298,305)--(310,305);
  \node[cl text] (witnesscondition) at (42,310)
    {If $x$ is taken under $g$, record its witness:};
  \node[cl text,font=\pdfiglabelbold] (witness) at (42,329)
    {$(g,\,x,\,\text{reason},\,\text{artifact-link})$};

  % Real text-node extents for the bounded offline geometry audit.
  \foreach \name in {operator,issue,grant,active,expiry,removed,each,
    conjunction,scope,stakes,reversibility,unexpired,unrevoked,all,admit,
    permission,noasking,otherwise,escalate,recipient,noexecution,next,
    witnesscondition,witness}{%
    \path let \p1=(\name.north west),\p2=(\name.south east) in
      \pgfextra{\typeout{CL-NODE: \name,\x1,\y1,\x2,\y2}};}
\end{tikzpicture}%
}
\caption{\textbf{Vision.} Permission is not execution, and an action decision does not renew the grant.}
\label{fig:consent-lifecycle}
\end{figure}

