{\footnotesize
\begin{tabularx}{\linewidth}{@{}c l >{\raggedright\arraybackslash}X c@{}}
\toprule
 & operation & effect on the buckets & $\Delta S_P$ \\
\midrule
1 & topUp$(u)$ & $W_P \mathrel{+}= u$ & $+u$ \\
2 & escrow$(b)$ & $W_P \mathrel{-}= b$, $E_P \mathrel{+}= b$ & $0$ \\
